<?php
function account_nav(array $u,string $active,bool $ordersOnly=false): void { ?>
<aside class="flow-account-nav flow-sage"><strong><?= e($u['first_name'].' '.$u['last_name']) ?></strong><small><?= e($u['email']) ?></small><hr>
<?php $links=$ordersOnly?['overview'=>['account','My account'],'orders'=>['orders','Order history'],'returns'=>['returns','Returns & cancellations']]:['overview'=>['account','Overview'],'profile'=>['account','Personal information'],'addresses'=>['account','Saved addresses'],'orders'=>['orders','Order history'],'settings'=>['account','Account settings'],'returns'=>['returns','Returns & cancellations']]; foreach($links as $key=>[$route,$label]): ?><a class="<?= $active===$key?'active':'' ?>" href="<?= url($route,$route==='account'?['tab'=>$key]:[]) ?>"><?= e($label) ?></a><?php endforeach; ?><hr><a href="<?= url('logout') ?>">Sign out</a></aside><?php }
function flow_order_items(int $id): array { return fetch_all('SELECT oi.*,p.slug,(SELECT path FROM product_images WHERE product_id=oi.product_id ORDER BY is_primary DESC,id LIMIT 1) AS image FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?',[$id]); }
function flow_items(array $items): void { foreach($items as $i): ?><div class="flow-item"><img src="<?= e(product_image(array_merge($i,['slug'=>$i['slug']??'']))) ?>" alt=""><div class="grow"><strong><?= e($i['product_name']) ?></strong><small><?= e($i['variant_label']) ?><br><?= (int)$i['qty'] ?> × <?= money($i['unit_price']) ?></small></div><strong><?= money($i['line_total']) ?></strong></div><?php endforeach; }
function flow_totals(array $o): void { ?><div class="line"><span>Subtotal</span><span><?= money($o['subtotal']) ?></span></div><?php if($o['discount']>0): ?><div class="line"><span>Discount</span><span>−<?= money($o['discount']) ?></span></div><?php endif; ?><div class="line"><span><?= $o['delivery_method']==='pickup'?'Café pickup':'Standard delivery' ?></span><span><?= money($o['delivery_fee']) ?></span></div><div class="line total"><span>Order total</span><strong><?= money($o['total']) ?></strong></div><?php }
